<!doctype html>
<html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>TV Event — {{ $event->name }}</title><style>:root{font-family:Inter,Arial,sans-serif;color:#14213b;background:#eef5ff}*{box-sizing:border-box}body{margin:0}.screen{min-height:100vh;padding:3vw}.head{display:flex;justify-content:space-between;align-items:flex-start;border-bottom:1px solid #cbdcf4;padding-bottom:2vw}.brand{font-weight:900;color:#1763cb;font-size:clamp(1rem,2vw,1.6rem)}h1{font-size:clamp(1.8rem,4vw,4rem);margin:.4em 0}.time{font-size:clamp(1rem,2vw,2rem);font-weight:800;text-align:right}.grid{display:grid;grid-template-columns:38% 1fr;gap:2vw;margin-top:2vw}.panel{background:#fff;border:1px solid #d5e1f2;border-radius:2vw;padding:2.2vw;min-height:50vh}.big{font-size:clamp(3rem,10vw,9rem);font-weight:900;color:#195ab8}.label{color:#6980a5;font-weight:700;font-size:clamp(.8rem,1.5vw,1.2rem)}.stats{display:grid;grid-template-columns:1fr 1fr;gap:1vw;margin-top:2vw}.stat{background:#d7e8ff;border-radius:1vw;padding:1.2vw;font-size:clamp(.8rem,1.4vw,1.1rem)}.stat strong{display:block;font-size:clamp(1.5rem,3vw,3rem);color:#1656b2}.list-viewport{position:relative;overflow:hidden;max-height:58vh;margin-top:1.5vw}.list-viewport:before,.list-viewport:after{content:"";position:absolute;z-index:2;left:0;right:0;height:4.5vh;pointer-events:none}.list-viewport:before{top:0;background:linear-gradient(#fff,transparent)}.list-viewport:after{bottom:0;background:linear-gradient(transparent,#fff)}.list-track{display:grid;gap:1vw}.list-track.is-scrolling{animation:event-scroll 26s linear infinite}.row{display:grid;grid-template-columns:28% 1fr auto;align-items:center;padding:1.2vw;border:1px solid #e0e8f4;border-radius:1vw;font-size:clamp(1rem,2vw,1.8rem);min-height:5.8vw}.row strong{color:#174f9e}.pill{padding:.4em .7em;border-radius:99px;font-size:.58em;font-weight:700;background:#fff0c9;color:#8b5c00}.pill.hadir{background:#d8f3df;color:#16733c}.pill.dilayani{background:#dbeaff;color:#1b5cab}.foot{color:#7790b7;margin-top:1.5vw;font-size:clamp(.75rem,1.2vw,1rem)}@keyframes event-scroll{0%,10%{transform:translateY(0)}90%,100%{transform:translateY(-50%)}}@media(max-width:720px){.grid{grid-template-columns:1fr}.panel{min-height:auto}.list-viewport{max-height:45vh}}</style></head>
<body><main class="screen"><header class="head"><div><div class="brand">SIOLA Q · TV EVENT</div><h1 id="event-name">{{ $event->name }}</h1></div><div class="time" id="clock">--:--:--</div></header><section class="grid"><div class="panel"><div class="label">PENDAFTAR EVENT</div><div class="big" id="registered">0</div><div class="stats"><div class="stat">Sudah hadir<strong id="checked-in">0</strong></div><div class="stat">Sisa kuota<strong id="remaining">0</strong></div></div></div><div class="panel"><div class="label">PESERTA TERBARU</div><div id="participants" class="list-viewport"></div></div></section><div class="foot">Diperbarui <span id="updated">-</span> · TV Event menampilkan nama tersamarkan</div></main><script>const endpoint=@json(route('event.tv.status',$event->tv_token));const clock=()=>document.getElementById('clock').textContent=new Intl.DateTimeFormat('id-ID',{hour:'2-digit',minute:'2-digit',second:'2-digit'}).format(new Date());const statusInfo=s=>s==='serving'?['Dilayani','dilayani']:s==='checked_in'?['Hadir','hadir']:['Terdaftar',''];async function load(){try{const r=await fetch(endpoint,{cache:'no-store'});if(!r.ok)return;const d=await r.json(),items=d.participants||[],scroll=items.length>=6,rows=items.map(p=>{const [label,css]=statusInfo(p.status);return `<div class="row"><strong>${p.ticket}</strong><span>${p.name}</span><span class="pill ${css}">${label}</span></div>`}).join('');document.getElementById('registered').textContent=d.registered;document.getElementById('checked-in').textContent=d.checked_in;document.getElementById('remaining').textContent=Math.max(d.quota-d.registered,0);document.getElementById('updated').textContent=d.updated_at+' WIB';document.getElementById('participants').innerHTML=items.length?`<div class="list-track ${scroll?'is-scrolling':''}">${rows}${scroll?rows:''}</div>`:'<div class="row"><span>-</span><span>Belum ada pendaftar</span><span></span></div>'}catch(e){}}clock();load();setInterval(clock,1000);setInterval(load,5000);</script></body></html>
